gainEs.source:
gainEs(amount: number): number {
    if (amount <= 0 || this.dead) return 0;
    const max = this.maxEs();
    if (max <= 0) return 0;
    const before = this.es;
    this.es = Math.min(max, this.es + amount);
    if (before < max - 0.001 && this.es >= max - 0.001) this.esJustFilled = true;
    return this.es - before;
  }

gainPoise.source:
gainPoise(amount: number): number {
    if (amount <= 0 || this.dead) return 0;
    const max = this.maxPoise();
    if (max <= 0) return 0;
    const cap = max * (1 + this.sheet.get('poiseOvercharge'));
    const before = this.poise;
    this.poise = Math.min(cap, this.poise + amount);
    return this.poise - before;
  }

maxPoise.source:
maxPoise(): number {
    // The held stance's kit counts (Unyielding Stance's 'guarding' grant).
    const sc = this.stanceRead();
    return this.sheet.get('poise', sc?.tags, sc?.extra);
  }

availableMaxMana.source:
availableMaxMana(): number {
    return Math.max(0, this.maxMana() - this.reservedMana);
  }

applyRestore.source:
private applyRestore(
    target: Actor,
    fx: { resource: 'life' | 'mana' | 'es' | 'poise'; amount: number; resetEsDelay?: boolean },
    opts?: { noEvent?: boolean; tags?: SkillTag[]; feedingCue?: import('../data/feedingCues').FeedingCueSpec | false },
  ): number {
    let landed = 0;
    if (fx.resource === 'life') {
      landed = target.healBy(fx.amount);
    } else if (fx.resource === 'mana') {
      const before = target.mana;
      target.mana = Math.min(target.availableMaxMana(), target.mana + fx.amount);
      landed = target.mana - before;
    } else if (fx.resource === 'poise') {
      landed = target.gainPoise(fx.amount);
    } else {
      landed = target.gainEs(fx.amount);
      if (fx.resetEsDelay) target.esDelay = 0;
    }
    if (fx.resource !== 'poise') noteRestoreGain(target, fx.resource, landed, opts?.feedingCue);
    if (landed > 0 && !opts?.noEvent && target.gainEvents.length < 64) {
      target.gainEvents.push({
        kind: 'restore', id: fx.resource, depth: 0,
        n: landed, tags: opts?.tags,
      });
    }
    return landed;
  }

